const fetch = require('node-fetch');

// The tool is now entirely dynamic and expects a beautifully engineered query string from the LLM
const requestBody = {
  api_key: $vars.tavilyApiKey,
  query: $input,
  search_depth: "advanced",
  include_answer: true,
  include_raw_content: true,
  max_results: 5
};

try {
  const response = await fetch(`https://api.tavily.com/search`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(requestBody)
  });

  const data = await response.json();

  if (!data.results || data.results.length === 0) {
      return `No verified results were found for query: "${$input}".`;
  }

  // Pure domain safety filter: block known non-official consumer forums or review aggregates
  const filteredResults = data.results.filter(r => {
      const url = r.url.toLowerCase();
      return !url.includes('blog') && 
             !url.includes('forum') && 
             !url.includes('reddit') && 
             !url.includes('youtube') && 
             !url.includes('wikipedia');
  });

  if (filteredResults.length === 0) {
      return `Results were located for "${$input}", but they failed the structural authenticity verification step.`;
  }

  const results = filteredResults.map(r => `Title: ${r.title}\nURL: ${r.url}\nContent: ${r.content}`).join("\n\n---\n\n");
  return data.answer ? `Summary: ${data.answer}\n\nDetailed Official Sources:\n${results}` : results;

} catch (error) {
    return `Error processing dynamic search execution: ${error.message}`;
}
